<script lang="ts">
	import PageLayout from '$components/PageLayout.svelte';
	import { userAccountData, diskSelectionData, showConfirmDialog } from '$lib/state.svelte';
	// @ts-expect-error — generated by Wails
	import { GetSelectedLanguage, GetLanguages, CheckRoot } from '@wails/go/gui/App.js';
	// @ts-expect-error — generated by Wails
	import { LogInfo } from '@wails/runtime/runtime';
	import { formatSize, MIN_DISK_SIZE_BYTES } from '$lib/types';

	interface Language {
		code: string;
		name: string;
		locale: string;
	}

	interface RootCheckResult {
		authorized: boolean;
		error?: string;
		message: string;
	}

	let languages = $state<Language[]>([]);
	let selectedLanguageName = $state<string>('—');
	let rootCheckResult = $state<RootCheckResult | null>(null);
	let rootCheckLoading = $state(true);

	const isDiskSizeSufficient = $derived.by(() => {
		if (!diskSelectionData.disk) return false;
		const size = parseInt(diskSelectionData.disk.size, 10);
		return !isNaN(size) && size >= MIN_DISK_SIZE_BYTES;
	});

	async function loadLanguageInfo(): Promise<void> {
		try {
			languages = await GetLanguages();
			const code = await GetSelectedLanguage();
			const lang = languages.find((l) => l.code === code);
			selectedLanguageName = lang?.name || code || '—';
		} catch {
			selectedLanguageName = '—';
		}
	}

	async function checkRootPrivileges(): Promise<void> {
		try {
			rootCheckResult = await CheckRoot();
		} catch (err) {
			rootCheckResult = {
				authorized: false,
				message: `Root check failed: ${err}`,
			};
		} finally {
			rootCheckLoading = false;
		}
	}

	loadLanguageInfo();
	checkRootPrivileges();

	// Intercept go-next event and show confirmation dialog
	$effect(() => {
		const handler = (e: Event) => {
			// If dialog is already showing (user clicked Yes), let the event through
			if (showConfirmDialog.value) return;
			showConfirmDialog.value = true;
			e.preventDefault();
		};
		document.addEventListener('go-next', handler);
		return () => document.removeEventListener('go-next', handler);
	});

	function handleConfirmYes(): void {
		LogInfo('[ConfirmationPage] User confirmed installation');
		document.dispatchEvent(new CustomEvent('go-next', { cancelable: true }));
	}

	function handleConfirmNo(): void {
		showConfirmDialog.value = false;
	}
</script>

<PageLayout title="Installation Summary">
	<div class="confirmation">
		<!-- Root Privileges Check -->
		<div class="root-check">
			{#if rootCheckLoading}
				<div class="root-check-status loading">
					<span class="spinner"></span>
					<span>Checking root privileges...</span>
				</div>
			{:else if rootCheckResult}
				<div class="root-check-status {rootCheckResult.authorized ? 'authorized' : 'unauthorized'}">
					{#if rootCheckResult.authorized}
						<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
							<path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
							<polyline points="22 4 12 14.01 9 11.01"></polyline>
						</svg>
						<span>{rootCheckResult.message}</span>
					{:else}
						<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
							<circle cx="12" cy="12" r="10"></circle>
							<line x1="15" y1="9" x2="9" y2="15"></line>
							<line x1="9" y1="9" x2="15" y2="15"></line>
						</svg>
						<span>{rootCheckResult.message}</span>
					{/if}
				</div>
			{/if}
		</div>

		<!-- Summary -->
		<div class="summary">
			<div class="summary-section">
				<h3 class="section-title">Language</h3>
				<p class="section-value">{selectedLanguageName}</p>
			</div>

			<div class="summary-section">
				<h3 class="section-title">User Account</h3>
				<p class="section-value">
					Username: <strong>{userAccountData.username || '—'}</strong>
				</p>
				{#if userAccountData.password}
					<p class="section-value">
						Password: <strong>{'●'.repeat(userAccountData.password.length)}</strong>
					</p>
				{/if}
			</div>

			<div class="summary-section">
				<h3 class="section-title">Target Disk</h3>
				{#if diskSelectionData.disk}
					<div class="disk-summary no-gap">
						<p class="section-value disk-name">
							{diskSelectionData.disk.model || 'Unknown'} ({formatSize(diskSelectionData.disk.size)} {diskSelectionData.disk.rotational ? 'HDD' : 'SSD'} {diskSelectionData.disk.trans?.toUpperCase() || ''})
						</p>
						<p class="disk-path">Device: <code>{diskSelectionData.disk.path}</code></p>
						<p class="disk-extra">
							Filesystem: <span class="tag fs-tag">{diskSelectionData.fileSystem || '—'}</span>
						</p>
						{#if diskSelectionData.disk.fstype}
							<p class="disk-extra">Existing filesystem: <span class="tag fstype-tag">{diskSelectionData.disk.fstype}</span></p>
						{/if}
						{#if diskSelectionData.disk.serial}
							<p class="disk-extra">Serial: <span class="tag serial-tag">{diskSelectionData.disk.serial}</span></p>
						{/if}
						{#if !isDiskSizeSufficient}
							<p class="disk-extra disk-size-error">⚠ Disk too small — minimum 8 GB required</p>
						{/if}
					</div>
				{:else}
					<p class="section-value error">No disk selected</p>
				{/if}
			</div>
		</div>
	</div>
</PageLayout>

